package com.notepocket.app;

import android.graphics.Typeface;
import android.text.*;
import android.text.style.*;
import org.json.*;
import java.util.*;

/** A complete, optional style for newly inserted text. Never touches inline media spans. */
final class TypingStyle {
    int color=PocketTheme.INK,size=18,highlight=0,bits=0;boolean underline,strike;
    TypingStyle copy(){TypingStyle s=new TypingStyle();s.color=color;s.size=size;s.highlight=highlight;s.bits=bits;s.underline=underline;s.strike=strike;return s;}
    static TypingStyle from(Spanned text,int position){TypingStyle s=new TypingStyle();if(text.length()==0)return s;int at=Math.min(text.length()-1,Math.max(0,position-1));for(CharacterStyle c:text.getSpans(at,at+1,CharacterStyle.class)){if(text.getSpanStart(c)>at||text.getSpanEnd(c)<=at)continue;CharacterStyle v=c.getUnderlying();if(v instanceof ForegroundColorSpan)s.color=((ForegroundColorSpan)v).getForegroundColor();else if(v instanceof BackgroundColorSpan)s.highlight=((BackgroundColorSpan)v).getBackgroundColor();else if(v instanceof AbsoluteSizeSpan&&((AbsoluteSizeSpan)v).getDip())s.size=((AbsoluteSizeSpan)v).getSize();else if(v instanceof StyleSpan)s.bits|=((StyleSpan)v).getStyle();else if(v instanceof UnderlineSpan)s.underline=true;else if(v instanceof StrikethroughSpan)s.strike=true;}return s;}
    String json(){try{return new JSONObject().put("color",color).put("size",size).put("highlight",highlight).put("bits",bits).put("underline",underline).put("strike",strike).toString();}catch(JSONException e){throw new IllegalStateException(e);}}
    static TypingStyle parse(String json){try{JSONObject j=new JSONObject(json);TypingStyle s=new TypingStyle();s.color=j.optInt("color",PocketTheme.INK)|0xff000000;s.size=Math.max(10,Math.min(48,j.optInt("size",18)));s.highlight=j.optInt("highlight");s.bits=j.optInt("bits")&3;s.underline=j.optBoolean("underline");s.strike=j.optBoolean("strike");return s;}catch(Exception e){return null;}}
    static CharacterStyle copySpan(CharacterStyle c){c=c.getUnderlying();if(c instanceof StyleSpan)return new StyleSpan(((StyleSpan)c).getStyle());if(c instanceof ForegroundColorSpan)return new ForegroundColorSpan(((ForegroundColorSpan)c).getForegroundColor());if(c instanceof BackgroundColorSpan)return new BackgroundColorSpan(((BackgroundColorSpan)c).getBackgroundColor());if(c instanceof AbsoluteSizeSpan)return new AbsoluteSizeSpan(((AbsoluteSizeSpan)c).getSize(),((AbsoluteSizeSpan)c).getDip());if(c instanceof RelativeSizeSpan)return new RelativeSizeSpan(((RelativeSizeSpan)c).getSizeChange());if(c instanceof UnderlineSpan)return new UnderlineSpan();if(c instanceof StrikethroughSpan)return new StrikethroughSpan();return null;}
    static void clear(Editable text,int lo,int hi){for(CharacterStyle c:text.getSpans(lo,hi,CharacterStyle.class)){CharacterStyle left=copySpan(c),right=copySpan(c);if(left==null)continue;int a=text.getSpanStart(c),b=text.getSpanEnd(c);if(a>=hi||b<=lo)continue;text.removeSpan(c);if(a<lo)text.setSpan(left,a,lo,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);if(b>hi)text.setSpan(right,hi,b,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}}
    void apply(Editable text,int lo,int hi){lo=Math.max(0,lo);hi=Math.min(text.length(),hi);if(lo>=hi)return;clear(text,lo,hi);if(bits!=0)put(text,new StyleSpan(bits),lo,hi);if(underline)put(text,new UnderlineSpan(),lo,hi);if(strike)put(text,new StrikethroughSpan(),lo,hi);put(text,new ForegroundColorSpan(color),lo,hi);put(text,new AbsoluteSizeSpan(size,true),lo,hi);if(highlight!=0)put(text,new BackgroundColorSpan(highlight),lo,hi);}
    private static void put(Editable text,CharacterStyle span,int lo,int hi){boolean expanded;do{expanded=false;for(CharacterStyle c:text.getSpans(Math.max(0,lo-1),Math.min(text.length(),hi+1),CharacterStyle.class)){if(!same(c.getUnderlying(),span))continue;int a=text.getSpanStart(c),b=text.getSpanEnd(c);if(b<lo||a>hi)continue;text.removeSpan(c);lo=Math.min(lo,a);hi=Math.max(hi,b);expanded=true;}}while(expanded);text.setSpan(span,lo,hi,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}
    private static boolean same(CharacterStyle a,CharacterStyle b){if(a.getClass()!=b.getClass())return false;if(a instanceof StyleSpan)return ((StyleSpan)a).getStyle()==((StyleSpan)b).getStyle();if(a instanceof ForegroundColorSpan)return ((ForegroundColorSpan)a).getForegroundColor()==((ForegroundColorSpan)b).getForegroundColor();if(a instanceof BackgroundColorSpan)return ((BackgroundColorSpan)a).getBackgroundColor()==((BackgroundColorSpan)b).getBackgroundColor();if(a instanceof AbsoluteSizeSpan)return ((AbsoluteSizeSpan)a).getSize()==((AbsoluteSizeSpan)b).getSize()&&((AbsoluteSizeSpan)a).getDip()==((AbsoluteSizeSpan)b).getDip();return a instanceof UnderlineSpan||a instanceof StrikethroughSpan;}
    String summary(){String name=color==0xffD12D39?"แดง":color==0xff216B58?"เขียว":color==0xff245BCC?"น้ำเงิน":color==0xff7B3FB0?"ม่วง":color==PocketTheme.INK?"ดำ":String.format(Locale.ROOT,"#%06X",color&0xffffff);return name+" · "+size+((bits&Typeface.BOLD)!=0?" · หนา":"")+((bits&Typeface.ITALIC)!=0?" · เอียง":"")+(underline?" · เส้นใต้":"")+(strike?" · ขีดฆ่า":"")+(highlight!=0?" · ไฮไลต์":"");}
}
